-- Phase 5: staff, teacher assignments and staff documents
create table if not exists public.staff(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,profile_id uuid references public.profiles(id) on delete set null,employee_no text not null,first_name text not null,last_name text,phone text,email text,designation text,department text,employment_type text not null default 'full-time' check(employment_type in ('full-time','part-time','contract','volunteer')),joining_date date,status text not null default 'active' check(status in ('active','inactive','on-leave','terminated')),qualifications jsonb not null default '[]'::jsonb,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(institution_id,employee_no));
create table if not exists public.teacher_subjects(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,staff_id uuid not null references public.staff(id) on delete cascade,subject_id uuid not null references public.subjects(id) on delete cascade,created_at timestamptz not null default now(),unique(staff_id,subject_id));
create table if not exists public.teacher_classes(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,staff_id uuid not null references public.staff(id) on delete cascade,class_id uuid not null references public.academic_classes(id) on delete cascade,section_id uuid references public.sections(id) on delete set null,is_class_teacher boolean not null default false,created_at timestamptz not null default now(),unique(staff_id,class_id,section_id));
create table if not exists public.staff_documents(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,staff_id uuid not null references public.staff(id) on delete cascade,document_type text not null,document_name text not null,storage_path text,issued_on date,expires_on date,notes text,created_at timestamptz not null default now());
create index if not exists staff_institution_status_idx on public.staff(institution_id,status); create index if not exists staff_profile_idx on public.staff(profile_id);
create index if not exists teacher_subjects_institution_idx on public.teacher_subjects(institution_id); create index if not exists teacher_subjects_subject_idx on public.teacher_subjects(subject_id);
create index if not exists teacher_classes_institution_idx on public.teacher_classes(institution_id); create index if not exists teacher_classes_class_idx on public.teacher_classes(class_id);
create index if not exists staff_documents_institution_idx on public.staff_documents(institution_id); create index if not exists staff_documents_staff_idx on public.staff_documents(staff_id);
alter table public.staff enable row level security; alter table public.teacher_subjects enable row level security; alter table public.teacher_classes enable row level security; alter table public.staff_documents enable row level security;
create policy staff_select on public.staff for select to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.view')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy staff_insert on public.staff for insert to authenticated with check ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy staff_update on public.staff for update to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid())))) with check ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy staff_delete on public.staff for delete to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.delete')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy teacher_subjects_select on public.teacher_subjects for select to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.view')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy teacher_subjects_write on public.teacher_subjects for all to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid())))) with check ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy teacher_classes_select on public.teacher_classes for select to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.view')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy teacher_classes_write on public.teacher_classes for all to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid())))) with check ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy staff_documents_select on public.staff_documents for select to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.view')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));
create policy staff_documents_write on public.staff_documents for all to authenticated using ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid())))) with check ((select app_private.is_super_admin()) or ((select app_private.has_permission('teachers.create')) and institution_id=(select p.institution_id from public.profiles p where p.id=(select auth.uid()))));